lock table public.guideline_versions in share row exclusive mode;
create temporary table population_batch on commit drop as
select * from jsonb_to_recordset($population$[{"id":"2a6b90b6-13a1-443f-a212-1c2f3975327d","title":"Chronic Kidney Disease","original_version_id":"2a6b90b6-13a1-443f-a212-1c2f3975327d","expected_hash":"9f8b0791aeb428127b7be7520be53cb0","source_url":"https://www.nice.org.uk/guidance/ng203/chapter/recommendations","source_title":"Chronic kidney disease: assessment and management","issuer":"NICE","scope":"Adults with suspected or established chronic kidney disease; this limited extraction covers eGFR, urine albumin:creatinine ratio, classification, progression and specialist-referral triggers.","content":{"id":"2a6b90b6-13a1-443f-a212-1c2f3975327d","title":"Chronic Kidney Disease","specialty":"Nephrology / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Persistent kidney structural or functional abnormality reduces filtration and homeostasis. Albuminuria and vascular/metabolic injury predict progression and cardiovascular events; comorbidity and medicines modify risk. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Persistent kidney structural or functional abnormality reduces filtration and homeostasis. Albuminuria and vascular/metabolic injury predict progression and cardiovascular events","comorbidity and medicines modify risk."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Chronic Kidney Disease, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Rapid decline or new nephritic features","Severe hyperkalaemia or acidosis","Pulmonary oedema or uraemic symptoms","Suspected obstruction or systemic inflammatory disease"]},"differentials":[{"condition":"AKI","distinguishingFeatures":"Serial values and clinical timing establish acute versus chronic change."},{"condition":"Transient albuminuria","distinguishingFeatures":"Repeat after infection or exercise and use appropriate sampling."},{"condition":"Obstructive or glomerular disease","distinguishingFeatures":"Symptoms, urine sediment, and imaging/serology guide work-up."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Repeat eGFR and urine albumin-to-creatinine ratio to confirm chronicity; blood pressure, electrolytes, CBC, urinalysis.","modalityTarget":"Repeat eGFR and urine albumin-to-creatinine ratio to confirm chronicity; blood pressure, electrolytes, CBC, urinalysis. — Chronic Kidney Disease","targetCondition":"Chronic Kidney Disease","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Check targeted cause and complication tests based on clinical stage and findings.","modalityTarget":"Check targeted cause and complication tests based on clinical stage and findings. — Cause, complication, or risk relevant to Chronic Kidney Disease","targetCondition":"Cause, complication, or risk relevant to Chronic Kidney Disease","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Chronic Kidney Disease","targetCondition":"Important alternative to Chronic Kidney Disease","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or established chronic kidney disease; this limited extraction covers eGFR, urine albumin:creatinine ratio, classification, progression and specialist-referral triggers. NICE NG203 is a UK guideline and requires reconciliation with current Saudi nephrology pathways, local laboratory reporting and referral capacity. The source names ACE inhibitors and angiotensin-receptor blockers but this extraction does not support a complete medicine choice, dose, route, frequency, duration or contraindication set. Existing inherited treatment text and references are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"160a2825-62d5-456a-8042-561249431a01","title":"Chronic kidney disease: assessment and management","issuer":"NICE","edition":"NG203, published 25 August 2021; updated 24 November 2021","url":"https://www.nice.org.uk/guidance/ng203/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.14, Table 1 and recommendations 1.5.5 to 1.5.7","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or established chronic kidney disease; this limited extraction covers eGFR, urine albumin:creatinine ratio, classification, progression and specialist-referral triggers."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Serum creatinine with estimated glomerular filtration rate","clinical_question":"Is reduced kidney function present and persistent?","expected_finding":"Use creatinine-based eGFR in adults; a new eGFR below 60 mL/min/1.73 m² should be repeated to confirm the result.","decision_rationale":"NICE uses eGFR to detect and classify reduced kidney function while recognising biological and analytical variability.","timeframe":"Repeat a new eGFR below 60 within 2 weeks; use serial results to establish chronicity and progression"},{"test":"Urine albumin:creatinine ratio","clinical_question":"Is clinically important albuminuria present?","expected_finding":"An ACR of 3 to 70 mg/mmol should be confirmed on a subsequent early-morning sample; an initial ACR of 70 mg/mmol or more does not require repeat confirmation.","decision_rationale":"Albuminuria is required with GFR category to classify CKD and informs referral and management.","timeframe":"At initial CKD assessment; confirm 3 to 70 mg/mmol using an early-morning sample"},{"test":"Kidney Failure Risk Equation","clinical_question":"Does the person meet a risk-based specialist-referral threshold?","expected_finding":"A 5-year risk of needing renal replacement therapy above 5% is one NICE referral criterion.","decision_rationale":"Risk prediction supplements eGFR, ACR, haematuria, blood pressure and rate-of-decline criteria.","timeframe":"Use in adults with CKD stages G3a to G5 when making referral decisions"}],"evidence":{"sources":[{"id":"160a2825-62d5-456a-8042-561249431a01","title":"Chronic kidney disease: assessment and management","issuer":"NICE","edition":"NG203, published 25 August 2021; updated 24 November 2021","url":"https://www.nice.org.uk/guidance/ng203/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.14, Table 1 and recommendations 1.5.5 to 1.5.7","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or established chronic kidney disease; this limited extraction covers eGFR, urine albumin:creatinine ratio, classification, progression and specialist-referral triggers."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Classify CKD using both GFR and ACR categories and document the cause when known.","timeframe":"After confirmed assessment"},{"instruction":"Refer for specialist assessment when a NICE criterion is met, including 5-year kidney-failure risk above 5%, ACR 70 mg/mmol or more, ACR above 30 mg/mmol with haematuria, defined sustained eGFR decline, or resistant hypertension.","timeframe":"When the criterion is identified"},{"instruction":"Review gaps: NICE NG203 is a UK guideline and requires reconciliation with current Saudi nephrology pathways, local laboratory reporting and referral capacity. The source names ACE inhibitors and angiotensin-receptor blockers but this extraction does not support a complete medicine choice, dose, route, frequency, duration or contraindication set. Existing inherited treatment text and references are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"160a2825-62d5-456a-8042-561249431a01","title":"Chronic kidney disease: assessment and management","issuer":"NICE","edition":"NG203, published 25 August 2021; updated 24 November 2021","url":"https://www.nice.org.uk/guidance/ng203/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.14, Table 1 and recommendations 1.5.5 to 1.5.7","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or established chronic kidney disease; this limited extraction covers eGFR, urine albumin:creatinine ratio, classification, progression and specialist-referral triggers."}}]},"nonClinicalManagement":{"patientEducation":["Explain chronic kidney disease in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Nephrology / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"e5bf7644-f824-4eca-8828-aacf30dad973","title":"Chronic Obstructive Pulmonary Disease","original_version_id":"e5bf7644-f824-4eca-8828-aacf30dad973","expected_hash":"408789f6810322ca6190ec566c08f7b1","source_url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","source_title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","scope":"People aged over 16 with suspected or diagnosed COPD; this limited extraction covers diagnostic spirometry, selected baseline tests, dyspnoea assessment and routine review.","content":{"id":"e5bf7644-f824-4eca-8828-aacf30dad973","title":"Chronic Obstructive Pulmonary Disease","specialty":"Respiratory Medicine / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Persistent airway and parenchymal changes cause expiratory flow limitation, air trapping, and impaired gas exchange. Exacerbations worsen symptoms and may accelerate loss of function. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Persistent airway and parenchymal changes cause expiratory flow limitation, air trapping, and impaired gas exchange. Exacerbations worsen symptoms and may accelerate loss of function.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Chronic Obstructive Pulmonary Disease, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["New haemoptysis or unexplained weight loss","Rapidly worsening breathlessness or cyanosis","Recurrent severe exacerbations","Resting hypoxaemia or hypercapnia symptoms"]},"differentials":[{"condition":"Asthma","distinguishingFeatures":"Variable symptoms and earlier onset may suggest asthma or overlap."},{"condition":"Heart failure","distinguishingFeatures":"Congestion and cardiac evaluation can identify coexisting disease."},{"condition":"Bronchiectasis or lung cancer","distinguishingFeatures":"Persistent purulent sputum, haemoptysis, or focal change needs assessment."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Post-bronchodilator spirometry; symptom/exacerbation assessment, oxygenation, imaging and comorbidity review as indicated.","modalityTarget":"Post-bronchodilator spirometry; symptom/exacerbation assessment, oxygenation, imaging and comorbidity review as indicated. — Chronic Obstructive Pulmonary Disease","targetCondition":"Chronic Obstructive Pulmonary Disease","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Review inhaler technique, smoking/exposure, vaccination and rehabilitation access.","modalityTarget":"Review inhaler technique, smoking/exposure, vaccination and rehabilitation access. — Cause, complication, or risk relevant to Chronic Obstructive Pulmonary Disease","targetCondition":"Cause, complication, or risk relevant to Chronic Obstructive Pulmonary Disease","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Chronic Obstructive Pulmonary Disease","targetCondition":"Important alternative to Chronic Obstructive Pulmonary Disease","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. People aged over 16 with suspected or diagnosed COPD; this limited extraction covers diagnostic spirometry, selected baseline tests, dyspnoea assessment and routine review. This older UK source requires reconciliation with current GOLD, Saudi respiratory guidance and local spirometry standards before approval. Interpretation should account for current GLI reference equations and population limitations. The source contains treatment recommendations, but this limited extraction does not verify a complete medicine regimen, inhaler choice, dose, device, duration or contraindication set. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"218534af-9d15-4a91-a262-35752fadb019","title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","edition":"NG115, published 5 December 2018; last updated 26 July 2019","url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.27 and 1.2.137 to 1.2.138","primary_source":true}],"selection_rationale":"Unverified scope: People aged over 16 with suspected or diagnosed COPD; this limited extraction covers diagnostic spirometry, selected baseline tests, dyspnoea assessment and routine review."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Post-bronchodilator spirometry","clinical_question":"Is persistent airflow obstruction present in a person with compatible symptoms and risk factors?","expected_finding":"Post-bronchodilator spirometry is used to confirm COPD; interpret the result with the clinical picture and alternative diagnoses.","decision_rationale":"NICE requires objective demonstration of airflow obstruction rather than diagnosis from symptoms alone.","timeframe":"At diagnostic assessment"},{"test":"Chest radiograph and full blood count","clinical_question":"Are an alternative diagnosis, comorbidity, anaemia or polycythaemia contributing?","expected_finding":"A chest radiograph and full blood count are included in initial diagnostic investigations.","decision_rationale":"These tests help identify alternative or associated disease that changes management.","timeframe":"At initial diagnostic work-up"},{"test":"Alpha-1 antitrypsin testing","clinical_question":"Is inherited alpha-1 antitrypsin deficiency plausible?","expected_finding":"Testing is considered for early-onset disease, minimal smoking history or family history.","decision_rationale":"A positive diagnosis affects counselling and specialist management.","timeframe":"When clinical features suggest inherited deficiency"}],"evidence":{"sources":[{"id":"218534af-9d15-4a91-a262-35752fadb019","title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","edition":"NG115, published 5 December 2018; last updated 26 July 2019","url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.27 and 1.2.137 to 1.2.138","primary_source":true}],"selection_rationale":"Unverified scope: People aged over 16 with suspected or diagnosed COPD; this limited extraction covers diagnostic spirometry, selected baseline tests, dyspnoea assessment and routine review."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Record breathlessness using the MRC dyspnoea scale and assess exacerbation history, smoking status, oxygen saturation, BMI and comorbidities.","timeframe":"At diagnosis and review"},{"instruction":"Review people with COPD at least annually, with more frequent review when clinically indicated.","timeframe":"At least every 12 months"},{"instruction":"Review gaps: This older UK source requires reconciliation with current GOLD, Saudi respiratory guidance and local spirometry standards before approval. Interpretation should account for current GLI reference equations and population limitations. The source contains treatment recommendations, but this limited extraction does not verify a complete medicine regimen, inhaler choice, dose, device, duration or contraindication set. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"218534af-9d15-4a91-a262-35752fadb019","title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","edition":"NG115, published 5 December 2018; last updated 26 July 2019","url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.27 and 1.2.137 to 1.2.138","primary_source":true}],"selection_rationale":"Unverified scope: People aged over 16 with suspected or diagnosed COPD; this limited extraction covers diagnostic spirometry, selected baseline tests, dyspnoea assessment and routine review."}}]},"nonClinicalManagement":{"patientEducation":["Explain chronic obstructive pulmonary disease in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Respiratory Medicine / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"433ede2c-6a49-4169-88ca-298ccf2cb065","title":"Colorectal Cancer Diagnosis and Treatment Planning","original_version_id":"433ede2c-6a49-4169-88ca-298ccf2cb065","expected_hash":"1e647c71b02039d2455e7a4e21f885c0","source_url":"https://www.nice.org.uk/guidance/ng151/chapter/recommendations","source_title":"Colorectal cancer","issuer":"NICE","scope":"Adults with confirmed or suspected colorectal cancer; this limited extraction covers staging, selected tumour biomarkers, multidisciplinary treatment planning and surveillance after curative treatment.","content":{"id":"433ede2c-6a49-4169-88ca-298ccf2cb065","title":"Colorectal Cancer Diagnosis and Treatment Planning","specialty":"Colorectal Surgery / Oncology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Colorectal malignancy develops through genetic and epigenetic change, with location and stage shaping symptoms and treatment. Multidisciplinary staging balances oncologic control with functional outcomes and patient priorities. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Colorectal malignancy develops through genetic and epigenetic change, with location and stage shaping symptoms and treatment. Multidisciplinary staging balances oncologic control with functional outcomes and patient priorities.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Colorectal Cancer Diagnosis and Treatment Planning, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Obstruction, perforation, or significant bleeding","Severe anaemia or malnutrition","Possible metastatic disease with organ compromise","Hereditary syndrome or multiple affected relatives"]},"differentials":[{"condition":"Benign polyp or inflammatory lesion","distinguishingFeatures":"Histology and complete colon evaluation establish diagnosis."},{"condition":"Gynaecologic or gastric source of anaemia","distinguishingFeatures":"Investigate alternative causes when lesion does not explain findings."},{"condition":"Synchronous colorectal lesion","distinguishingFeatures":"Complete colon assessment is important when feasible."}],"investigations":{"ruleIn":[{"tier":"advancedImaging","testName":"Colonoscopy with biopsy and full colon evaluation; CT staging and baseline laboratory assessment through local pathway.","modalityTarget":"Colonoscopy with biopsy and full colon evaluation; CT staging and baseline laboratory assessment through local pathway. — Colorectal Cancer Diagnosis and Treatment Planning","targetCondition":"Colorectal Cancer Diagnosis and Treatment Planning","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Pathology and tumour board testing should follow current local oncology standards, not textbook algorithms alone.","modalityTarget":"Pathology and tumour board testing should follow current local oncology standards, not textbook algorithms alone. — Cause, complication, or risk relevant to Colorectal Cancer Diagnosis and Treatment Planning","targetCondition":"Cause, complication, or risk relevant to Colorectal Cancer Diagnosis and Treatment Planning","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Colorectal Cancer Diagnosis and Treatment Planning","targetCondition":"Important alternative to Colorectal Cancer Diagnosis and Treatment Planning","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with confirmed or suspected colorectal cancer; this limited extraction covers staging, selected tumour biomarkers, multidisciplinary treatment planning and surveillance after curative treatment. The current NICE page links to technology appraisals that may change medicine eligibility. This extraction does not reproduce systemic anticancer regimens, doses, contraindications, operative detail or radiotherapy schedules. All treatment must be reconciled with current Saudi oncology protocols, tumour site and stage, pathology, molecular results, performance status and multidisciplinary review. Existing inherited sections and references are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"19591cdc-da1a-47d1-ad8e-33692c1961f9","title":"Colorectal cancer","issuer":"NICE","edition":"NG151, published 29 January 2020; recommendations page includes updates through 2025","url":"https://www.nice.org.uk/guidance/ng151/chapter/recommendations","locator":"Recommendations on staging, molecular testing, treatment planning and follow-up after curative treatment","primary_source":true}],"selection_rationale":"Unverified scope: Adults with confirmed or suspected colorectal cancer; this limited extraction covers staging, selected tumour biomarkers, multidisciplinary treatment planning and surveillance after curative treatment."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Histopathology and staging imaging","clinical_question":"Is colorectal malignancy confirmed and what is the local and distant extent?","expected_finding":"Tissue diagnosis and stage-appropriate imaging establish tumour type, local extent and metastatic disease for treatment planning.","decision_rationale":"Treatment selection depends on confirmed pathology, tumour site and stage.","timeframe":"Before definitive treatment planning"},{"test":"RAS and BRAF V600E mutation testing","clinical_question":"Does metastatic disease have a molecular profile that changes systemic-treatment options?","expected_finding":"RAS and BRAF V600E status should be available for people with metastatic colorectal cancer who may be candidates for systemic treatment.","decision_rationale":"These biomarkers affect eligibility for targeted treatment and prognosis.","timeframe":"Before selecting systemic treatment for metastatic disease"},{"test":"Mismatch-repair or microsatellite-instability assessment","clinical_question":"Does the tumour have deficient mismatch repair or high microsatellite instability?","expected_finding":"MMR or MSI status informs hereditary assessment and treatment options in relevant disease settings.","decision_rationale":"Molecular classification can change counselling and systemic-treatment decisions.","timeframe":"During pathological and molecular work-up"}],"evidence":{"sources":[{"id":"19591cdc-da1a-47d1-ad8e-33692c1961f9","title":"Colorectal cancer","issuer":"NICE","edition":"NG151, published 29 January 2020; recommendations page includes updates through 2025","url":"https://www.nice.org.uk/guidance/ng151/chapter/recommendations","locator":"Recommendations on staging, molecular testing, treatment planning and follow-up after curative treatment","primary_source":true}],"selection_rationale":"Unverified scope: Adults with confirmed or suspected colorectal cancer; this limited extraction covers staging, selected tumour biomarkers, multidisciplinary treatment planning and surveillance after curative treatment."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Review confirmed disease in a colorectal multidisciplinary team using tumour site, stage, pathology, molecular findings, comorbidity, performance status and patient preferences.","timeframe":"Before definitive treatment"},{"instruction":"After curative treatment, use surveillance that includes CEA testing and CT of the chest, abdomen and pelvis during the first 3 years, individualised to recurrence risk and treatment suitability.","timeframe":"During the first 3 years after curative treatment"},{"instruction":"Review gaps: The current NICE page links to technology appraisals that may change medicine eligibility. This extraction does not reproduce systemic anticancer regimens, doses, contraindications, operative detail or radiotherapy schedules. All treatment must be reconciled with current Saudi oncology protocols, tumour site and stage, pathology, molecular results, performance status and multidisciplinary review. Existing inherited sections and references are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"19591cdc-da1a-47d1-ad8e-33692c1961f9","title":"Colorectal cancer","issuer":"NICE","edition":"NG151, published 29 January 2020; recommendations page includes updates through 2025","url":"https://www.nice.org.uk/guidance/ng151/chapter/recommendations","locator":"Recommendations on staging, molecular testing, treatment planning and follow-up after curative treatment","primary_source":true}],"selection_rationale":"Unverified scope: Adults with confirmed or suspected colorectal cancer; this limited extraction covers staging, selected tumour biomarkers, multidisciplinary treatment planning and surveillance after curative treatment."}}]},"nonClinicalManagement":{"patientEducation":["Explain colorectal cancer diagnosis and treatment planning in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Colorectal Surgery / Oncology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"d0389517-2846-49bc-8a01-eb7265f8e139","title":"Colorectal Cancer Screening","original_version_id":"d0389517-2846-49bc-8a01-eb7265f8e139","expected_hash":"c9784bb168c5e372479e346e4a659268","source_url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening","source_title":"USPSTF Colorectal Cancer: Screening Final Recommendation Statement","issuer":"Other","scope":"Asymptomatic average-risk adults aged 45 years or older without prior colorectal cancer, adenomatous polyps, inflammatory bowel disease or a known high-risk genetic syndrome.","content":{"id":"d0389517-2846-49bc-8a01-eb7265f8e139","title":"Colorectal Cancer Screening","specialty":"Primary Care / Gastroenterology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Most colorectal cancers arise through progressive neoplastic change over time, allowing screening to detect precursor lesions or early cancer. Benefit depends on risk category, test completion, and diagnostic follow-through. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Most colorectal cancers arise through progressive neoplastic change over time, allowing screening to detect precursor lesions or early cancer. Benefit depends on risk category, test completion, and diagnostic follow-through.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Colorectal Cancer Screening, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Rectal bleeding, iron-deficiency anaemia or persistent bowel change is diagnostic work-up","Strong family or hereditary cancer pattern","Unintentional weight loss or abdominal mass","Positive stool test requires timely colon evaluation"]},"differentials":[{"condition":"Haemorrhoids","distinguishingFeatures":"Do not use as a reason to dismiss unexplained bleeding."},{"condition":"Inflammatory bowel disease","distinguishingFeatures":"May need surveillance rather than population screening."},{"condition":"Functional bowel disorder","distinguishingFeatures":"Persistent alarm features still require evaluation."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review symptoms, family history, prior polyps/IBD, comorbidity and current Saudi programme eligibility.","modalityTarget":"Review symptoms, family history, prior polyps/IBD, comorbidity and current Saudi programme eligibility. — Colorectal Cancer Screening","targetCondition":"Colorectal Cancer Screening","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Select nationally recommended screening test and create a tracked follow-up plan for positive results.","modalityTarget":"Select nationally recommended screening test and create a tracked follow-up plan for positive results. — Cause, complication, or risk relevant to Colorectal Cancer Screening","targetCondition":"Cause, complication, or risk relevant to Colorectal Cancer Screening","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Colorectal Cancer Screening","targetCondition":"Important alternative to Colorectal Cancer Screening","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Asymptomatic average-risk adults aged 45 years or older without prior colorectal cancer, adenomatous polyps, inflammatory bowel disease or a known high-risk genetic syndrome. This is a United States recommendation and must be reconciled with the current Saudi national screening programme, local test availability, eligibility and colonoscopy capacity. It does not apply to symptomatic or high-risk people. Harms, bowel preparation, sedation, test-quality requirements and post-polypectomy surveillance are not fully specified in this extraction. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"022af0bc-9958-43d5-bb3b-7b1ad1ef11b6","title":"USPSTF Colorectal Cancer: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 18 May 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening","locator":"Recommendation Summary and Practice Considerations: Patient Population Under Consideration and Screening Tests","primary_source":true}],"selection_rationale":"Unverified scope: Asymptomatic average-risk adults aged 45 years or older without prior colorectal cancer, adenomatous polyps, inflammatory bowel disease or a known high-risk genetic syndrome."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Stool-based screening","clinical_question":"Which non-invasive screening interval is suitable for an average-risk adult?","expected_finding":"Supported strategies include annual FIT and stool DNA-FIT every 1 to 3 years.","decision_rationale":"Regular stool testing can reduce colorectal-cancer mortality when positive results receive colonoscopy.","timeframe":"FIT every year or stool DNA-FIT every 1 to 3 years"},{"test":"Direct visualisation screening","clinical_question":"Which structural examination and interval is suitable?","expected_finding":"Supported strategies include CT colonography every 5 years, flexible sigmoidoscopy every 5 years, colonoscopy every 10 years, or flexible sigmoidoscopy every 10 years combined with annual FIT.","decision_rationale":"These strategies balance test burden, interval and ability to detect colorectal lesions.","timeframe":"At the interval specified for the selected strategy"},{"test":"Diagnostic colonoscopy after an abnormal screening test","clinical_question":"Has a non-colonoscopy screening test returned an abnormal result?","expected_finding":"The screening benefit is not achieved unless an abnormal stool, CT-colonography or sigmoidoscopy result receives colonoscopic evaluation.","decision_rationale":"Colonoscopy completes diagnostic evaluation and permits biopsy or polyp management.","timeframe":"Promptly after an abnormal screening result"}],"evidence":{"sources":[{"id":"022af0bc-9958-43d5-bb3b-7b1ad1ef11b6","title":"USPSTF Colorectal Cancer: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 18 May 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening","locator":"Recommendation Summary and Practice Considerations: Patient Population Under Consideration and Screening Tests","primary_source":true}],"selection_rationale":"Unverified scope: Asymptomatic average-risk adults aged 45 years or older without prior colorectal cancer, adenomatous polyps, inflammatory bowel disease or a known high-risk genetic syndrome."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer screening to average-risk adults aged 45 to 75 using an evidence-supported strategy selected through shared decision-making.","timeframe":"From age 45 through 75"},{"instruction":"Selectively offer screening at ages 76 to 85 according to overall health, prior screening history and preferences; do not continue routine screening after age 85.","timeframe":"Individual decision from age 76 to 85"},{"instruction":"Review gaps: This is a United States recommendation and must be reconciled with the current Saudi national screening programme, local test availability, eligibility and colonoscopy capacity. It does not apply to symptomatic or high-risk people. Harms, bowel preparation, sedation, test-quality requirements and post-polypectomy surveillance are not fully specified in this extraction.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"022af0bc-9958-43d5-bb3b-7b1ad1ef11b6","title":"USPSTF Colorectal Cancer: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 18 May 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening","locator":"Recommendation Summary and Practice Considerations: Patient Population Under Consideration and Screening Tests","primary_source":true}],"selection_rationale":"Unverified scope: Asymptomatic average-risk adults aged 45 years or older without prior colorectal cancer, adenomatous polyps, inflammatory bowel disease or a known high-risk genetic syndrome."}}]},"nonClinicalManagement":{"patientEducation":["Explain colorectal cancer screening in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Primary Care / Gastroenterology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"a1010000-0000-4000-8000-000000000004","title":"Community-Acquired Pneumonia","original_version_id":"a1010000-0000-4000-8000-000000000004","expected_hash":"4c1ca00a9781547db3d7363cf53620bb","source_url":"https://www.nice.org.uk/guidance/ng250/chapter/recommendations","source_title":"Pneumonia: diagnosis and management","issuer":"NICE","scope":"Adults with community-acquired pneumonia; this limited extraction covers severity assessment, hospital diagnosis, selected microbiology and one first-choice low-severity oral antibiotic regimen.","content":{"id":"a1010000-0000-4000-8000-000000000004","title":"Community-Acquired Pneumonia","specialty":"Internal Medicine, Respiratory Medicine and Infectious Diseases","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2021-01-01","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Community-acquired pneumonia is infection of the distal airways and alveoli acquired outside hospital or early after admission. Alveolar inflammation and exudate impair ventilation and gas exchange; systemic inflammatory effects may cause sepsis and organ dysfunction.","keyMechanisms":["Pathogen aspiration or inhalation overcomes airway and innate immune defences.","Alveolar neutrophilic inflammation and fluid cause consolidation and ventilation-perfusion mismatch.","Host response varies with age, comorbidity, immune status and pathogen virulence.","Complications include parapneumonic effusion, empyema, lung abscess, respiratory failure and sepsis."]},"presentation":{"symptoms":["Acute cough with or without sputum","Fever, rigors or malaise","Dyspnoea or pleuritic chest pain","Confusion or functional decline, especially in older adults"],"physicalSigns":["Tachypnoea, hypoxaemia or increased work of breathing","Focal crackles, bronchial breathing or dullness to percussion","Fever or hypothermia with tachycardia","Confusion, hypotension or poor perfusion in severe disease"],"redFlags":["Respiratory failure, exhaustion or rapidly increasing oxygen need","Shock, altered mental status, oliguria or other sepsis-associated organ dysfunction","Multilobar disease, cavitation or a large pleural effusion","Immunocompromise, aspiration risk or failure to improve on appropriate initial therapy"]},"differentials":[{"condition":"Pulmonary embolism","distinguishingFeatures":"Abrupt pleuritic pain or dyspnoea, thrombosis risk and limited infective prodrome; imaging shows vascular rather than air-space disease."},{"condition":"Acute heart failure","distinguishingFeatures":"Orthopnoea, bilateral congestion, raised jugular venous pressure and cardiac dysfunction."},{"condition":"Viral respiratory infection without pneumonia","distinguishingFeatures":"Diffuse upper-respiratory features without focal consolidation or compatible chest imaging."},{"condition":"Pulmonary tuberculosis","distinguishingFeatures":"Subacute constitutional symptoms, epidemiologic risk, upper-lobe or cavitary change and specific microbiology."}],"investigations":{"ruleIn":[{"tier":"firstLineImaging","testName":"Chest radiograph","modalityTarget":"Chest radiograph — Pulmonary air-space infection","targetCondition":"Pulmonary air-space infection","expectedFinding":"New focal or multifocal infiltrate compatible with pneumonia.","clinicalRationale":"Supports diagnosis, extent assessment and detection of effusion or another thoracic process in hospital-managed disease."},{"tier":"laboratory","testName":"Pulse oximetry and blood gas when severe","modalityTarget":"Pulse oximetry and blood gas when severe — Gas-exchange impairment","targetCondition":"Gas-exchange impairment","expectedFinding":"Hypoxaemia, with acidaemia or ventilatory failure in advanced disease.","clinicalRationale":"Determines oxygen and ventilatory support needs."},{"tier":"laboratory","testName":"Microbiology selected by severity","modalityTarget":"Microbiology selected by severity — Causative pathogen","targetCondition":"Causative pathogen","expectedFinding":"A plausible bacterial or viral pathogen in good-quality respiratory, blood or molecular samples.","clinicalRationale":"Severe or epidemiologically important disease benefits most from organism identification and antimicrobial narrowing."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Electrocardiogram and cardiac assessment","modalityTarget":"Electrocardiogram and cardiac assessment — Heart failure or acute coronary syndrome","targetCondition":"Heart failure or acute coronary syndrome","expectedFinding":"No primary cardiac process sufficient to explain the presentation.","clinicalRationale":"Cardiac disease commonly mimics or coexists with pneumonia."},{"tier":"advancedImaging","testName":"CT chest or pleural ultrasound when indicated","modalityTarget":"CT chest or pleural ultrasound when indicated — Pulmonary embolism, malignancy, abscess or complicated effusion","targetCondition":"Pulmonary embolism, malignancy, abscess or complicated effusion","expectedFinding":"No alternative lesion, or a complication is identified for targeted management.","clinicalRationale":"Reserved for diagnostic uncertainty, complication assessment or treatment failure."}]},"clinicalManagement":[{"id":"severity","title":"Confirm diagnosis and assess severity","timeframe":"At presentation","actions":["Assess oxygenation, sepsis features, comorbidity and ability to take oral treatment.","Use a validated severity tool as an adjunct, not a replacement for clinical judgement.","Identify aspiration, resistant-organism, travel and immunocompromise risks."]},{"id":"antimicrobial","title":"Start empiric antimicrobial therapy","timeframe":"Promptly after diagnosis; immediately when sepsis or shock is present","actions":["Select generic therapy from the current MOH/local formulary according to severity, allergy, recent exposure and the local antibiogram.","Obtain indicated cultures first only when this will not delay urgent therapy.","Document indication, route, review date and planned duration."]},{"id":"support","title":"Provide supportive care","timeframe":"Concurrent with antimicrobial treatment","actions":["Titrate oxygen to the appropriate clinical target.","Treat sepsis, fluid deficit, pain and fever while accounting for cardiac and renal status.","Provide thrombosis prevention and early mobilisation for admitted patients when appropriate."]},{"id":"review-response","title":"Review response and complications","timeframe":"Formal review within 24 to 48 hours or sooner if deteriorating","actions":["Reassess observations, oxygen need, mental status, oral intake and inflammatory/organ-function trends.","Narrow or change antimicrobials using microbiology and clinical response.","Investigate empyema, abscess, resistant pathogen, obstruction or an alternative diagnosis when improvement is absent."]},{"id":"switch-discharge","title":"Switch route and plan discharge","timeframe":"When clinically stable","actions":["Switch from intravenous to oral treatment when stability and gastrointestinal absorption permit.","Use the shortest effective guideline-concordant course and document the stop date.","Arrange follow-up imaging only for persistent symptoms or guideline-defined risk, not automatically for every patient."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[{"indication":"First-choice oral treatment for low-severity community-acquired pneumonia in adults","patientGroup":"Adults with low-severity community-acquired pneumonia when penicillin is suitable","genericName":"Amoxicillin","dose":"500 mg","route":"Oral","frequency":"Three times daily","duration":"5 days","adjustments":["Use an alternative regimen when penicillin allergy or another contraindication is present.","Reconcile renal adjustment, pregnancy, interactions and local resistance with the current local formulary."],"monitoring":["Review clinical response and signs of instability.","Review microbiology when obtained and narrow or change therapy as indicated."],"sourceTitle":"Pneumonia: diagnosis and management","sourceUrl":"https://www.nice.org.uk/guidance/ng250/chapter/recommendations","sourceEdition":"NG250, published 2025; recommendations retrieved 12 October 2026; Recommendations on CRB65 and CURB65, hospital chest radiography, microbiological testing, Table 1 adult antibiotics and review of treatment duration"}],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with community-acquired pneumonia; this limited extraction covers severity assessment, hospital diagnosis, selected microbiology and one first-choice low-severity oral antibiotic regimen. This UK guideline requires reconciliation with Saudi antimicrobial policy, local resistance, allergy history, renal and hepatic function, pregnancy, QT risk, interactions and microbiology. The exact contraindication set is not provided on the retrieved recommendation page and must be checked against the current product information and local formulary before use. Moderate and high-severity regimens, aspiration, immunocompromise and recent healthcare exposure are outside this limited extraction. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"847ad18c-2b9f-4d6f-a733-023a5ae68bc9","title":"Pneumonia: diagnosis and management","issuer":"NICE","edition":"NG250, published 2025; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng250/chapter/recommendations","locator":"Recommendations on CRB65 and CURB65, hospital chest radiography, microbiological testing, Table 1 adult antibiotics and review of treatment duration","primary_source":true}],"selection_rationale":"Unverified scope: Adults with community-acquired pneumonia; this limited extraction covers severity assessment, hospital diagnosis, selected microbiology and one first-choice low-severity oral antibiotic regimen."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"CRB65 or CURB65 severity assessment","clinical_question":"What is the risk of mortality and appropriate place of care?","expected_finding":"Use CRB65 in primary care and CURB65 in hospital alongside clinical judgement.","decision_rationale":"Severity scoring supports escalation and site-of-care decisions but does not replace clinical assessment.","timeframe":"At first assessment"},{"test":"Chest radiograph","clinical_question":"Is pneumonia confirmed in a person admitted to hospital?","expected_finding":"Hospital services should establish the diagnosis, including chest radiography, promptly after presentation.","decision_rationale":"Rapid confirmation supports timely treatment and review of alternative diagnoses.","timeframe":"Within 4 hours of hospital presentation"},{"test":"Microbiological testing","clinical_question":"Is pathogen testing likely to change treatment?","expected_finding":"Routine microbiological testing is not recommended for low-severity community-acquired pneumonia; consider testing when severity or clinical context warrants it.","decision_rationale":"Testing is targeted to cases where results can influence antibiotic choice or public-health action.","timeframe":"Before or early in antibiotic treatment when indicated"}],"evidence":{"sources":[{"id":"847ad18c-2b9f-4d6f-a733-023a5ae68bc9","title":"Pneumonia: diagnosis and management","issuer":"NICE","edition":"NG250, published 2025; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng250/chapter/recommendations","locator":"Recommendations on CRB65 and CURB65, hospital chest radiography, microbiological testing, Table 1 adult antibiotics and review of treatment duration","primary_source":true}],"selection_rationale":"Unverified scope: Adults with community-acquired pneumonia; this limited extraction covers severity assessment, hospital diagnosis, selected microbiology and one first-choice low-severity oral antibiotic regimen."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Start antibiotics promptly after diagnosis and reassess if symptoms worsen rapidly, fail to improve as expected or suggest sepsis.","timeframe":"As soon as pneumonia is diagnosed"},{"instruction":"Stop antibiotic treatment after 5 days unless microbiological results or clinical instability indicate a longer course.","timeframe":"Review at day 5"},{"instruction":"Review gaps: This UK guideline requires reconciliation with Saudi antimicrobial policy, local resistance, allergy history, renal and hepatic function, pregnancy, QT risk, interactions and microbiology. The exact contraindication set is not provided on the retrieved recommendation page and must be checked against the current product information and local formulary before use. Moderate and high-severity regimens, aspiration, immunocompromise and recent healthcare exposure are outside this limited extraction. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"847ad18c-2b9f-4d6f-a733-023a5ae68bc9","title":"Pneumonia: diagnosis and management","issuer":"NICE","edition":"NG250, published 2025; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng250/chapter/recommendations","locator":"Recommendations on CRB65 and CURB65, hospital chest radiography, microbiological testing, Table 1 adult antibiotics and review of treatment duration","primary_source":true}],"selection_rationale":"Unverified scope: Adults with community-acquired pneumonia; this limited extraction covers severity assessment, hospital diagnosis, selected microbiology and one first-choice low-severity oral antibiotic regimen."}}]},"nonClinicalManagement":{"patientEducation":["Explain the expected recovery trajectory and that cough and fatigue may outlast fever.","Give return precautions for worsening breathlessness, confusion, cyanosis, chest pain or inability to maintain intake.","Explain antimicrobial adherence and why unused antibiotics should not be saved or shared."],"lifestyleAndDiet":["Encourage hydration and nutrition as tolerated.","Offer smoking-cessation support.","Review influenza, pneumococcal and other indicated vaccination after recovery."],"mdtReferrals":["Critical care for respiratory failure or shock","Respiratory medicine for complications, recurrent pneumonia or diagnostic uncertainty","Microbiology or infectious diseases for resistant organisms, severe immunocompromise or treatment failure","Speech and language therapy for suspected aspiration"],"dischargeCriteria":["Vital signs and oxygen requirement are stable at an appropriate baseline.","The patient can take oral medicine and maintain hydration and nutrition.","A safe antimicrobial plan, follow-up ownership and return precautions are documented."],"followUpPlan":"Arrange clinical review based on severity and comorbidity; follow pending cultures, reassess non-resolution, and consider interval chest imaging for persistent symptoms or higher malignancy risk according to local policy."}}},{"id":"a44b31ff-1839-4db9-aec2-f73fcaef4d5f","title":"Conservative Kidney Care Planning","original_version_id":"a44b31ff-1839-4db9-aec2-f73fcaef4d5f","expected_hash":"cd2ebf621195297a9283d013e7f115f4","source_url":"https://www.nice.org.uk/guidance/ng107/chapter/recommendations","source_title":"Renal replacement therapy and conservative management","issuer":"NICE","scope":"Adults approaching kidney failure who are considering renal replacement therapy or comprehensive conservative kidney care; this limited extraction covers early assessment, shared decisions and symptom-focused planning.","content":{"id":"a44b31ff-1839-4db9-aec2-f73fcaef4d5f","title":"Conservative Kidney Care Planning","specialty":"Nephrology / Palliative Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Advanced kidney disease causes fluid, electrolyte, metabolic, and uraemic symptoms. Conservative kidney management is active care focused on symptoms, function, and quality of life when dialysis is not chosen or is unlikely to meet patient goals. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Advanced kidney disease causes fluid, electrolyte, metabolic, and uraemic symptoms. Conservative kidney management is active care focused on symptoms, function, and quality of life when dialysis is not chosen or is unlikely to meet patient goals.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Conservative Kidney Care Planning, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Refractory fluid overload, hyperkalaemia, acidosis, or uraemic symptoms needing urgent review","Conflict or uncertainty about capacity and preferences","Uncontrolled pain, pruritus, nausea, or breathlessness","Caregiver inability to sustain home plan"]},"differentials":[{"condition":"Reversible AKI or obstruction","distinguishingFeatures":"Assess and treat when consistent with goals."},{"condition":"Depression affecting decision","distinguishingFeatures":"Offer support before interpreting preference."},{"condition":"Dialysis as a preference-sensitive choice","distinguishingFeatures":"Present options without coercion."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review eGFR trajectory, symptoms, complications, function, cognition, medication burden and prior expressed preferences.","modalityTarget":"Review eGFR trajectory, symptoms, complications, function, cognition, medication burden and prior expressed preferences. — Conservative Kidney Care Planning","targetCondition":"Conservative Kidney Care Planning","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use proportionate tests and renal-palliative consultation; create a written crisis and symptom plan.","modalityTarget":"Use proportionate tests and renal-palliative consultation; create a written crisis and symptom plan. — Cause, complication, or risk relevant to Conservative Kidney Care Planning","targetCondition":"Cause, complication, or risk relevant to Conservative Kidney Care Planning","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Conservative Kidney Care Planning","targetCondition":"Important alternative to Conservative Kidney Care Planning","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults approaching kidney failure who are considering renal replacement therapy or comprehensive conservative kidney care; this limited extraction covers early assessment, shared decisions and symptom-focused planning. This older UK guideline requires reconciliation with current Saudi nephrology, transplantation, dialysis and palliative-care pathways. Prognostic tools, emergency dialysis indications, medicine prescribing, exact symptom-control doses and contraindications are not verified in this extraction. Existing inherited sections and references are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"574792ce-e4fb-4265-8ff9-c056121b4bc6","title":"Renal replacement therapy and conservative management","issuer":"NICE","edition":"NG107, published 3 October 2018","url":"https://www.nice.org.uk/guidance/ng107/chapter/recommendations","locator":"Recommendations on indications for renal replacement therapy or conservative management, information and decision-making, and dietary assessment","primary_source":true}],"selection_rationale":"Unverified scope: Adults approaching kidney failure who are considering renal replacement therapy or comprehensive conservative kidney care; this limited extraction covers early assessment, shared decisions and symptom-focused planning."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Multidisciplinary kidney-failure assessment","clinical_question":"Is kidney failure likely within the planning horizon and what options fit the person's clinical state and goals?","expected_finding":"Assessment integrates kidney trajectory, symptoms, comorbidity, expected quality of life, life expectancy and personal preferences.","decision_rationale":"The choice between renal replacement therapy and conservative management should be made before a crisis and revisited as circumstances change.","timeframe":"Begin at least 1 year before renal replacement therapy is likely to be needed"},{"test":"Structured symptom review","clinical_question":"Which physical, psychological, social or spiritual symptoms require treatment or support?","expected_finding":"Ongoing review identifies symptom burden and changing supportive-care needs.","decision_rationale":"Conservative kidney care is an active, comprehensive pathway centred on quality of life.","timeframe":"Throughout conservative management and whenever condition or goals change"},{"test":"Specialist renal dietetic assessment","clinical_question":"Can nutrition advice improve symptoms and safety without causing malnutrition?","expected_finding":"A specialist renal dietitian assesses dietary needs and individualises advice.","decision_rationale":"Dietary restrictions and symptom-focused changes require assessment of nutritional risk and preferences.","timeframe":"During planning and review"}],"evidence":{"sources":[{"id":"574792ce-e4fb-4265-8ff9-c056121b4bc6","title":"Renal replacement therapy and conservative management","issuer":"NICE","edition":"NG107, published 3 October 2018","url":"https://www.nice.org.uk/guidance/ng107/chapter/recommendations","locator":"Recommendations on indications for renal replacement therapy or conservative management, information and decision-making, and dietary assessment","primary_source":true}],"selection_rationale":"Unverified scope: Adults approaching kidney failure who are considering renal replacement therapy or comprehensive conservative kidney care; this limited extraction covers early assessment, shared decisions and symptom-focused planning."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer balanced information and a choice between appropriate renal replacement options and conservative management, using joint decision-making.","timeframe":"During advance planning and at major clinical changes"},{"instruction":"Document goals, preferred place of care, escalation decisions, symptom plan and how the decision will be reviewed.","timeframe":"After shared decision-making and whenever preferences change"},{"instruction":"Review gaps: This older UK guideline requires reconciliation with current Saudi nephrology, transplantation, dialysis and palliative-care pathways. Prognostic tools, emergency dialysis indications, medicine prescribing, exact symptom-control doses and contraindications are not verified in this extraction. Existing inherited sections and references are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"574792ce-e4fb-4265-8ff9-c056121b4bc6","title":"Renal replacement therapy and conservative management","issuer":"NICE","edition":"NG107, published 3 October 2018","url":"https://www.nice.org.uk/guidance/ng107/chapter/recommendations","locator":"Recommendations on indications for renal replacement therapy or conservative management, information and decision-making, and dietary assessment","primary_source":true}],"selection_rationale":"Unverified scope: Adults approaching kidney failure who are considering renal replacement therapy or comprehensive conservative kidney care; this limited extraction covers early assessment, shared decisions and symptom-focused planning."}}]},"nonClinicalManagement":{"patientEducation":["Explain conservative kidney care planning in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Nephrology / Palliative Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"a1010000-0000-4000-8000-000000000003","title":"Deep-Vein Thrombosis and Pulmonary Embolism","original_version_id":"a1010000-0000-4000-8000-000000000003","expected_hash":"8588a8a1311faee1a2099e21a04879a8","source_url":"https://www.nice.org.uk/guidance/ng158/chapter/recommendations","source_title":"Venous thromboembolic diseases: diagnosis, management and thrombophilia testing","issuer":"NICE","scope":"Adults with suspected or confirmed deep-vein thrombosis or pulmonary embolism; this limited extraction covers Wells-based diagnostic pathways, interim anticoagulation safeguards and minimum treatment duration.","content":{"id":"a1010000-0000-4000-8000-000000000003","title":"Deep-Vein Thrombosis and Pulmonary Embolism","specialty":"Emergency Medicine, Internal Medicine and Haematology","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2024-09-04","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Venous thromboembolism results from venous stasis, endothelial injury and hypercoagulability. A deep-vein thrombus may obstruct limb venous return or embolise to pulmonary arteries, increasing dead space and pulmonary vascular resistance and, in severe cases, causing right-ventricular failure and shock.","keyMechanisms":["Thrombus formation is promoted by immobility, surgery, cancer, oestrogen exposure, pregnancy and inherited or acquired thrombophilia.","Pulmonary arterial obstruction produces ventilation-perfusion mismatch and hypoxaemia.","Acute right-ventricular pressure overload can reduce left-ventricular filling and systemic cardiac output.","Residual venous obstruction and valve damage contribute to post-thrombotic syndrome; persistent vascular obstruction may cause chronic thromboembolic pulmonary hypertension."]},"presentation":{"symptoms":["Unilateral leg pain or swelling","Sudden unexplained dyspnoea","Pleuritic chest pain, cough, haemoptysis or syncope","Reduced exercise tolerance with recent immobility, surgery, cancer or prior thrombosis"],"physicalSigns":["Unilateral pitting oedema, calf asymmetry or deep venous tenderness","Tachycardia, tachypnoea or hypoxaemia","Signs of right-heart strain such as raised jugular venous pressure","Hypotension or poor perfusion in high-risk pulmonary embolism"],"redFlags":["Haemodynamic instability, syncope with persistent hypotension or obstructive-shock features","Severe hypoxaemia, rapidly escalating oxygen requirement or cardiac arrest","Threatened limb with massive swelling, cyanosis or severe pain","Active major bleeding or another absolute barrier to anticoagulation in a patient with confirmed or highly suspected VTE"]},"differentials":[{"condition":"Cellulitis","distinguishingFeatures":"Superficial erythema, warmth and a possible portal of entry with inflammatory features rather than isolated deep venous tenderness."},{"condition":"Ruptured Baker cyst","distinguishingFeatures":"Posterior knee pathology with fluid tracking into the calf and diagnostic ultrasound findings."},{"condition":"Acute coronary syndrome","distinguishingFeatures":"Pressure-type pain, ischaemic electrocardiographic change or a coronary biomarker pattern rather than pleuritic pain and right-heart strain."},{"condition":"Pneumonia or pneumothorax","distinguishingFeatures":"Focal infective symptoms or unilateral absent breath sounds with confirmatory chest imaging."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Compression ultrasonography","modalityTarget":"Compression ultrasonography — Proximal lower-limb DVT","targetCondition":"Proximal lower-limb DVT","expectedFinding":"Non-compressible venous segment or directly visualised thrombus.","clinicalRationale":"First-line anatomical confirmation for suspected proximal DVT."},{"tier":"advancedImaging","testName":"CT pulmonary angiography","modalityTarget":"CT pulmonary angiography — Pulmonary embolism","targetCondition":"Pulmonary embolism","expectedFinding":"Intraluminal filling defect in a pulmonary artery.","clinicalRationale":"Confirms pulmonary embolism and describes clot burden while also identifying some alternative thoracic diagnoses."},{"tier":"specializedAdjunctive","testName":"Echocardiography in unstable PE","modalityTarget":"Echocardiography in unstable PE — Right-ventricular pressure overload","targetCondition":"Right-ventricular pressure overload","expectedFinding":"Right-ventricular dilatation or dysfunction compatible with acute pressure overload.","clinicalRationale":"Supports urgent risk stratification when instability makes definitive imaging unsafe or delayed."}],"ruleOut":[{"tier":"laboratory","testName":"High-sensitivity D-dimer in an appropriate low-probability pathway","modalityTarget":"High-sensitivity D-dimer in an appropriate low-probability pathway — Acute VTE","targetCondition":"Acute VTE","expectedFinding":"A negative result below the assay's validated threshold makes acute VTE unlikely in the selected population.","clinicalRationale":"Avoids unnecessary imaging only after structured clinical-probability assessment."},{"tier":"laboratory","testName":"Ventilation-perfusion imaging","modalityTarget":"Ventilation-perfusion imaging — Pulmonary embolism when CTPA is unsuitable","targetCondition":"Pulmonary embolism when CTPA is unsuitable","expectedFinding":"Normal perfusion argues strongly against PE; a mismatched perfusion defect supports it.","clinicalRationale":"Provides an alternative when contrast, radiation distribution or renal considerations make CTPA unsuitable."}]},"clinicalManagement":[{"id":"probability","title":"Estimate clinical probability","timeframe":"At first assessment","actions":["Use a validated DVT or PE clinical-probability tool within its intended population.","Check haemodynamic stability and bleeding risk before selecting the diagnostic pathway.","Do not use a D-dimer to rule out VTE when clinical probability is high."]},{"id":"diagnose","title":"Obtain definitive imaging","timeframe":"Urgently according to probability and stability","actions":["Arrange compression ultrasonography for suspected DVT and CTPA or appropriate ventilation-perfusion imaging for suspected PE.","Give interim therapeutic anticoagulation when indicated by the approved pathway and imaging is delayed, after checking contraindications.","Obtain baseline blood count, renal and liver function, coagulation studies and pregnancy testing when relevant without delaying urgent treatment."]},{"id":"anticoagulate","title":"Start anticoagulation","timeframe":"Once VTE is confirmed or interim treatment is indicated","actions":["Select a locally formulary-approved anticoagulant based on renal and hepatic function, cancer, pregnancy potential, interactions, bleeding risk and patient preference.","Use generic agents and approved dosing references; do not derive dosing from this data record.","Document intended duration and the review point for extension or cessation."]},{"id":"escalate-pe","title":"Manage high-risk pulmonary embolism","timeframe":"Immediately","actions":["Activate critical-care and senior specialist support for haemodynamic instability.","Consider systemic thrombolysis or another reperfusion strategy only after rapid assessment of contraindications and local capability.","Provide respiratory and circulatory support while definitive therapy is organised."],"branches":[{"condition":"Anticoagulation is contraindicated","actions":["Seek urgent haematology or vascular advice.","Consider a temporary mechanical strategy only when guideline criteria are met, with an explicit retrieval plan."]}]},{"id":"secondary-prevention","title":"Plan secondary prevention","timeframe":"Before discharge","actions":["Classify the event as provoked, unprovoked or cancer-associated and document persistent risk factors.","Review adherence, interactions and bleeding precautions.","Avoid routine thrombophilia testing when it will not change management; seek specialist advice for selected cases."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or confirmed deep-vein thrombosis or pulmonary embolism; this limited extraction covers Wells-based diagnostic pathways, interim anticoagulation safeguards and minimum treatment duration. This UK guideline requires reconciliation with current Saudi VTE pathways, local imaging access, pregnancy and cancer protocols, renal and hepatic function, bleeding risk, interactions and product information. Although apixaban and rivaroxaban are named, the retrieved page does not provide a complete dose, route, frequency, switching, duration and contraindication set in this extraction, so no medicine regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"f22da2ef-dc68-459c-80a8-126067fedd11","title":"Venous thromboembolic diseases: diagnosis, management and thrombophilia testing","issuer":"NICE","edition":"NG158, published 26 March 2020; updated 2 August 2023","url":"https://www.nice.org.uk/guidance/ng158/chapter/recommendations","locator":"Recommendations 1.1.2 to 1.1.21 and 1.3.1 to 1.3.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed deep-vein thrombosis or pulmonary embolism; this limited extraction covers Wells-based diagnostic pathways, interim anticoagulation safeguards and minimum treatment duration."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Two-level DVT Wells score with proximal-leg-vein ultrasound and D-dimer pathway","clinical_question":"How likely is DVT and which test is required next?","expected_finding":"Use the two-level DVT Wells score; likely DVT proceeds urgently to proximal-leg-vein ultrasound, while D-dimer participates in the pathway according to probability and imaging result.","decision_rationale":"Pretest probability guides safe sequencing of D-dimer, imaging and interim anticoagulation.","timeframe":"At first assessment; obtain definitive testing within the NICE time windows"},{"test":"Two-level PE Wells score with CTPA or D-dimer pathway","clinical_question":"How likely is pulmonary embolism and which test is required next?","expected_finding":"Use the two-level PE Wells score; likely PE proceeds to CTPA when suitable, while D-dimer is used for unlikely PE.","decision_rationale":"Structured probability assessment reduces delayed diagnosis and unnecessary imaging.","timeframe":"At first assessment; obtain definitive testing urgently"},{"test":"Baseline full blood count, renal and hepatic function, PT and APTT","clinical_question":"Are there baseline abnormalities that affect anticoagulant safety or selection?","expected_finding":"Obtain baseline blood count, kidney and liver function and coagulation tests, but do not delay interim therapeutic anticoagulation while awaiting results.","decision_rationale":"Baseline results guide safe continuation and choice of anticoagulant.","timeframe":"At initiation; review results within 24 hours"}],"evidence":{"sources":[{"id":"f22da2ef-dc68-459c-80a8-126067fedd11","title":"Venous thromboembolic diseases: diagnosis, management and thrombophilia testing","issuer":"NICE","edition":"NG158, published 26 March 2020; updated 2 August 2023","url":"https://www.nice.org.uk/guidance/ng158/chapter/recommendations","locator":"Recommendations 1.1.2 to 1.1.21 and 1.3.1 to 1.3.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed deep-vein thrombosis or pulmonary embolism; this limited extraction covers Wells-based diagnostic pathways, interim anticoagulation safeguards and minimum treatment duration."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Give interim therapeutic anticoagulation when indicated if definitive diagnostic testing cannot be completed within the recommended timeframe, then review once results are available.","timeframe":"During diagnostic delay"},{"instruction":"For confirmed proximal DVT or PE, provide anticoagulation for at least 3 months and review ongoing treatment according to provoking factors, bleeding risk and preferences.","timeframe":"Minimum 3 months, followed by reassessment"},{"instruction":"Review gaps: This UK guideline requires reconciliation with current Saudi VTE pathways, local imaging access, pregnancy and cancer protocols, renal and hepatic function, bleeding risk, interactions and product information. Although apixaban and rivaroxaban are named, the retrieved page does not provide a complete dose, route, frequency, switching, duration and contraindication set in this extraction, so no medicine regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"f22da2ef-dc68-459c-80a8-126067fedd11","title":"Venous thromboembolic diseases: diagnosis, management and thrombophilia testing","issuer":"NICE","edition":"NG158, published 26 March 2020; updated 2 August 2023","url":"https://www.nice.org.uk/guidance/ng158/chapter/recommendations","locator":"Recommendations 1.1.2 to 1.1.21 and 1.3.1 to 1.3.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed deep-vein thrombosis or pulmonary embolism; this limited extraction covers Wells-based diagnostic pathways, interim anticoagulation safeguards and minimum treatment duration."}}]},"nonClinicalManagement":{"patientEducation":["Explain clot symptoms, anticoagulant purpose, adherence and what to do after a missed dose using the medicine-specific approved information.","Provide urgent warning signs for recurrent PE and major bleeding.","Discuss procedure, dental and pregnancy-planning precautions before any anticoagulant change."],"lifestyleAndDiet":["Encourage mobilisation as tolerated once anticoagulation and clinical stability permit.","Reduce prolonged immobility during travel and recovery and maintain hydration when appropriate.","Address smoking, obesity and other modifiable vascular risks without implying that lifestyle replaces anticoagulation."],"mdtReferrals":["Haematology for recurrent, unusual-site or selected unprovoked VTE","Oncology for suspected or active cancer-associated thrombosis","Vascular or interventional service for threatened limb or selected reperfusion decisions","Obstetric medicine for pregnancy or postpartum VTE"],"dischargeCriteria":["Haemodynamics and oxygenation are stable and validated outpatient-risk criteria are met where outpatient care is proposed.","Anticoagulant access, renal-function appropriateness, administration and follow-up are confirmed.","Bleeding and recurrence precautions are understood and a responsible service owns pending results."],"followUpPlan":"Review early after discharge for symptoms, bleeding, adherence and renal function where relevant; reassess treatment duration at the guideline-defined milestone and investigate persistent dyspnoea for post-PE complications."}}},{"id":"732644b9-0497-44a8-bfc2-0fca5dfc7392","title":"Delirium and Agitation Near End of Life","original_version_id":"732644b9-0497-44a8-bfc2-0fca5dfc7392","expected_hash":"f7442b3c7faa4bfc167f459650656221","source_url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","source_title":"Care of dying adults in the last days of life","issuer":"NICE","scope":"Adults thought to be in the last days of life who develop anxiety, delirium or agitation; this limited extraction covers reversible causes, non-drug measures and medicine-class trial decisions.","content":{"id":"732644b9-0497-44a8-bfc2-0fca5dfc7392","title":"Delirium and Agitation Near End of Life","specialty":"Palliative Medicine / Geriatrics","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Delirium is an acute disturbance of attention and awareness caused by interacting vulnerability and precipitating factors. Near end of life, illness, medicines, dehydration, pain, retention, and environment may contribute. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Delirium is an acute disturbance of attention and awareness caused by interacting vulnerability and precipitating factors. Near end of life, illness, medicines, dehydration, pain, retention, and environment may contribute.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Delirium and Agitation Near End of Life, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Seizure, focal deficit, or sudden severe headache","Respiratory compromise or suspected toxicity","Unsafe agitation or risk of injury","Family distress with unresolved goals or uncertainty"]},"differentials":[{"condition":"Dementia progression","distinguishingFeatures":"Acute fluctuation and inattention suggest delirium over baseline decline."},{"condition":"Depression or anxiety","distinguishingFeatures":"May coexist but does not explain acute altered attention alone."},{"condition":"Medication toxicity, infection, retention, constipation, dehydration","distinguishingFeatures":"Common reversible contributors to assess."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Collateral baseline and time course, medication review, focused neurological/physical examination, hydration, pain, bladder/bowel and infection assessment.","modalityTarget":"Collateral baseline and time course, medication review, focused neurological/physical examination, hydration, pain, bladder/bowel and infection assessment. — Delirium and Agitation Near End of Life","targetCondition":"Delirium and Agitation Near End of Life","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Target tests to reversible causes and goals; use validated delirium assessment where available.","modalityTarget":"Target tests to reversible causes and goals; use validated delirium assessment where available. — Cause, complication, or risk relevant to Delirium and Agitation Near End of Life","targetCondition":"Cause, complication, or risk relevant to Delirium and Agitation Near End of Life","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Delirium and Agitation Near End of Life","targetCondition":"Important alternative to Delirium and Agitation Near End of Life","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults thought to be in the last days of life who develop anxiety, delirium or agitation; this limited extraction covers reversible causes, non-drug measures and medicine-class trial decisions. This is an older UK guideline and must be reconciled with current Saudi palliative-care policy and local specialist protocols. It does not specify an exact drug, dose, route, frequency, duration or complete contraindication set for benzodiazepines or antipsychotics in the retrieved recommendations, so no medicine regimen is encoded. Existing inherited symptom-control text is not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"9fe47ae0-79d0-4fcc-9b99-42e0b9bdb5fe","title":"Care of dying adults in the last days of life","issuer":"NICE","edition":"NG31, published 16 December 2015","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","locator":"Recommendations 1.5.23 to 1.5.28: managing anxiety, delirium and agitation","primary_source":true}],"selection_rationale":"Unverified scope: Adults thought to be in the last days of life who develop anxiety, delirium or agitation; this limited extraction covers reversible causes, non-drug measures and medicine-class trial decisions."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Clinical assessment for reversible causes of agitation or delirium","clinical_question":"Is distress caused by pain, a full bladder or rectum, metabolic disturbance, medicine effects or another reversible factor?","expected_finding":"Identify and treat reversible causes where this is consistent with the person's goals and last-days-of-life plan.","decision_rationale":"Agitation can be a manifestation of untreated physical distress or delirium rather than a primary psychiatric symptom.","timeframe":"At onset and after each intervention"},{"test":"Assessment of anxiety, delirium and sedation burden","clinical_question":"Which syndrome is most likely and has treatment reduced distress without unwanted sedation?","expected_finding":"Repeated bedside assessment guides whether non-drug measures, a medicine-class trial or specialist advice is appropriate.","decision_rationale":"The treatment approach differs for anxiety and delirium and must remain proportionate to comfort goals.","timeframe":"Before treatment and frequently after treatment"}],"evidence":{"sources":[{"id":"9fe47ae0-79d0-4fcc-9b99-42e0b9bdb5fe","title":"Care of dying adults in the last days of life","issuer":"NICE","edition":"NG31, published 16 December 2015","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","locator":"Recommendations 1.5.23 to 1.5.28: managing anxiety, delirium and agitation","primary_source":true}],"selection_rationale":"Unverified scope: Adults thought to be in the last days of life who develop anxiety, delirium or agitation; this limited extraction covers reversible causes, non-drug measures and medicine-class trial decisions."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Use non-pharmacological management and address reversible causes before or alongside medicine when appropriate.","timeframe":"Immediately and throughout care"},{"instruction":"Consider a benzodiazepine trial for anxiety or agitation and an antipsychotic trial for delirium or agitation, using the current local palliative protocol and specialist advice.","timeframe":"When symptoms remain distressing after assessment"},{"instruction":"Seek specialist palliative-care advice if diagnosis is uncertain, treatment does not work or causes unwanted sedation.","timeframe":"Promptly when any criterion is present"},{"instruction":"Review gaps: This is an older UK guideline and must be reconciled with current Saudi palliative-care policy and local specialist protocols. It does not specify an exact drug, dose, route, frequency, duration or complete contraindication set for benzodiazepines or antipsychotics in the retrieved recommendations, so no medicine regimen is encoded. Existing inherited symptom-control text is not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"9fe47ae0-79d0-4fcc-9b99-42e0b9bdb5fe","title":"Care of dying adults in the last days of life","issuer":"NICE","edition":"NG31, published 16 December 2015","url":"https://www.nice.org.uk/guidance/ng31/chapter/recommendations","locator":"Recommendations 1.5.23 to 1.5.28: managing anxiety, delirium and agitation","primary_source":true}],"selection_rationale":"Unverified scope: Adults thought to be in the last days of life who develop anxiety, delirium or agitation; this limited extraction covers reversible causes, non-drug measures and medicine-class trial decisions."}}]},"nonClinicalManagement":{"patientEducation":["Explain delirium and agitation near end of life in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Palliative Medicine / Geriatrics","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"e483d190-076c-49b3-881c-78ca823af167","title":"Diabetes Screening in At-Risk Adults","original_version_id":"e483d190-076c-49b3-881c-78ca823af167","expected_hash":"2fa7984b209f4d027c2df5971d3071de","source_url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes/","source_title":"USPSTF Prediabetes and Type 2 Diabetes: Screening Final Recommendation Statement","issuer":"Other","scope":"Nonpregnant asymptomatic adults aged 35 to 70 years who have overweight or obesity; this limited extraction covers screening tests, diagnostic thresholds and repeat interval.","content":{"id":"e483d190-076c-49b3-881c-78ca823af167","title":"Diabetes Screening in At-Risk Adults","specialty":"Primary Care / Public Health","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Type 2 diabetes often develops gradually through insulin resistance and beta-cell dysfunction, allowing a period of asymptomatic dysglycaemia. Screening aims to identify people likely to benefit from preventive support and earlier care. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Type 2 diabetes often develops gradually through insulin resistance and beta-cell dysfunction, allowing a period of asymptomatic dysglycaemia. Screening aims to identify people likely to benefit from preventive support and earlier care.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Diabetes Screening in At-Risk Adults, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Classic symptoms with marked glucose elevation require prompt diagnostic assessment","Pregnancy or recent gestational diabetes has separate follow-up needs","Rapid weight loss or ketosis needs urgent evaluation","Discordant tests require clinical interpretation"]},"differentials":[{"condition":"Transient stress hyperglycaemia","distinguishingFeatures":"Repeat testing after acute illness if appropriate."},{"condition":"Medication-induced dysglycaemia","distinguishingFeatures":"Review glucocorticoids and other risks."},{"condition":"Type 1 diabetes","distinguishingFeatures":"Symptoms, ketosis, or rapid progression changes urgency."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Use HbA1c, fasting glucose, or other locally adopted test according to patient factors and national policy.","modalityTarget":"Use HbA1c, fasting glucose, or other locally adopted test according to patient factors and national policy. — Diabetes Screening in At-Risk Adults","targetCondition":"Diabetes Screening in At-Risk Adults","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Confirm abnormal results when required and assess renal, cardiovascular, and pregnancy history.","modalityTarget":"Confirm abnormal results when required and assess renal, cardiovascular, and pregnancy history. — Cause, complication, or risk relevant to Diabetes Screening in At-Risk Adults","targetCondition":"Cause, complication, or risk relevant to Diabetes Screening in At-Risk Adults","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Diabetes Screening in At-Risk Adults","targetCondition":"Important alternative to Diabetes Screening in At-Risk Adults","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Nonpregnant asymptomatic adults aged 35 to 70 years who have overweight or obesity; this limited extraction covers screening tests, diagnostic thresholds and repeat interval. This is a United States preventive recommendation and requires reconciliation with current Saudi diabetes screening policy, ethnicity-specific risk, gestational diabetes history, younger high-risk groups and local laboratory units. It is not a diagnostic pathway for symptomatic hyperglycaemia, pregnancy or acute metabolic decompensation. Medicine prevention is not encoded. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"608d3027-e53f-4b20-9958-ab06aa93874e","title":"USPSTF Prediabetes and Type 2 Diabetes: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 24 August 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes/","locator":"Recommendation Summary and Practice Considerations: Screening Tests, Screening Intervals and Preventive Interventions","primary_source":true}],"selection_rationale":"Unverified scope: Nonpregnant asymptomatic adults aged 35 to 70 years who have overweight or obesity; this limited extraction covers screening tests, diagnostic thresholds and repeat interval."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Fasting plasma glucose","clinical_question":"Is fasting glucose in the normal, prediabetes or diabetes range?","expected_finding":"Prediabetes is 100 to 125 mg/dL; diabetes is 126 mg/dL or higher.","decision_rationale":"Fasting plasma glucose is one accepted screening test.","timeframe":"At screening; confirm a diabetes-range result with repeat testing"},{"test":"Haemoglobin A1c","clinical_question":"Does longer-term glycaemia meet a prediabetes or diabetes threshold?","expected_finding":"Prediabetes is 5.7% to 6.4%; diabetes is 6.5% or higher.","decision_rationale":"HbA1c is an accepted screening test and does not require fasting.","timeframe":"At screening; confirm a diabetes-range result with repeat testing"},{"test":"75 g oral glucose tolerance test","clinical_question":"Does the 2-hour glucose meet a prediabetes or diabetes threshold?","expected_finding":"Prediabetes is 140 to 199 mg/dL; diabetes is 200 mg/dL or higher at 2 hours.","decision_rationale":"The oral glucose tolerance test can detect dysglycaemia not apparent on fasting glucose or HbA1c.","timeframe":"At screening when selected; confirm a diabetes-range result"}],"evidence":{"sources":[{"id":"608d3027-e53f-4b20-9958-ab06aa93874e","title":"USPSTF Prediabetes and Type 2 Diabetes: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 24 August 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes/","locator":"Recommendation Summary and Practice Considerations: Screening Tests, Screening Intervals and Preventive Interventions","primary_source":true}],"selection_rationale":"Unverified scope: Nonpregnant asymptomatic adults aged 35 to 70 years who have overweight or obesity; this limited extraction covers screening tests, diagnostic thresholds and repeat interval."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Screen eligible adults aged 35 to 70 who have overweight or obesity and offer or refer people with prediabetes to effective preventive interventions.","timeframe":"At eligibility assessment"},{"instruction":"After a normal result, repeating screening every 3 years is a reasonable approach, adjusted for risk and local policy.","timeframe":"Approximately every 3 years"},{"instruction":"Review gaps: This is a United States preventive recommendation and requires reconciliation with current Saudi diabetes screening policy, ethnicity-specific risk, gestational diabetes history, younger high-risk groups and local laboratory units. It is not a diagnostic pathway for symptomatic hyperglycaemia, pregnancy or acute metabolic decompensation. Medicine prevention is not encoded.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"608d3027-e53f-4b20-9958-ab06aa93874e","title":"USPSTF Prediabetes and Type 2 Diabetes: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 24 August 2021","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/screening-for-prediabetes-and-type-2-diabetes/","locator":"Recommendation Summary and Practice Considerations: Screening Tests, Screening Intervals and Preventive Interventions","primary_source":true}],"selection_rationale":"Unverified scope: Nonpregnant asymptomatic adults aged 35 to 70 years who have overweight or obesity; this limited extraction covers screening tests, diagnostic thresholds and repeat interval."}}]},"nonClinicalManagement":{"patientEducation":["Explain diabetes screening in at-risk adults in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Primary Care / Public Health","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"625f0d83-3863-47f9-a64e-55c0355f3240","title":"Diabetic Ketoacidosis","original_version_id":"625f0d83-3863-47f9-a64e-55c0355f3240","expected_hash":"bf336af5ef9dbac8ebb0d408d84ca331","source_url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf","source_title":"The Management of Diabetic Ketoacidosis in Adults","issuer":"Other","scope":"Adults with diabetic ketoacidosis; this limited extraction covers diagnostic criteria, initial 0.9% sodium chloride, fixed-rate intravenous soluble human insulin, potassium thresholds, dextrose addition, monitoring and biochemical resolution.","content":{"id":"625f0d83-3863-47f9-a64e-55c0355f3240","title":"Diabetic Ketoacidosis","specialty":"Endocrinology / Emergency Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b004","lastReviewed":"2026-10-10","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Insulin deficiency and counter-regulatory hormones increase lipolysis and hepatic ketone production; osmotic diuresis produces water and electrolyte loss. Infection, interrupted insulin, new diabetes, medicines, or acute stress may precipitate crisis. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Insulin deficiency and counter-regulatory hormones increase lipolysis and hepatic ketone production","osmotic diuresis produces water and electrolyte loss. Infection, interrupted insulin, new diabetes, medicines, or acute stress may precipitate crisis."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Diabetic Ketoacidosis, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Shock or severe dehydration","Reduced consciousness or inability to protect airway","Severe acidosis or dangerous potassium disturbance","Pregnancy or suspected cerebral injury"]},"differentials":[{"condition":"Hyperosmolar hyperglycaemic state","distinguishingFeatures":"More profound hyperosmolality and usually less prominent ketosis/acidosis; mixed presentations occur."},{"condition":"Starvation/alcoholic ketosis","distinguishingFeatures":"Exposure history and biochemical pattern differ."},{"condition":"Sepsis or acute abdomen","distinguishingFeatures":"May precipitate crisis or coexist; do not attribute all pain to DKA."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Bedside glucose and ketones; venous blood gas, electrolytes, renal function, anion gap and osmolality.","modalityTarget":"Bedside glucose and ketones; venous blood gas, electrolytes, renal function, anion gap and osmolality. — Diabetic Ketoacidosis","targetCondition":"Diabetic Ketoacidosis","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"specializedAdjunctive","testName":"ECG and directed tests for infection, ischaemia, pregnancy, or another precipitant.","modalityTarget":"ECG and directed tests for infection, ischaemia, pregnancy, or another precipitant. — Cause, complication, or risk relevant to Diabetic Ketoacidosis","targetCondition":"Cause, complication, or risk relevant to Diabetic Ketoacidosis","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Diabetic Ketoacidosis","targetCondition":"Important alternative to Diabetic Ketoacidosis","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[{"indication":"Fixed-rate intravenous insulin infusion for adult diabetic ketoacidosis","patientGroup":"Adults meeting biochemical DKA criteria; use specialist adjustment for pregnancy, renal failure, heart failure, older age and young adults","genericName":"Soluble human insulin","dose":"0.1 units/kg/hour, prepared as 50 units soluble human insulin in 50 mL 0.9% sodium chloride","route":"Intravenous infusion","frequency":"Continuous fixed-rate infusion","duration":"Continue until ketones are below 0.6 mmol/L and venous pH is above 7.3, with clinical review and safe transition to subcutaneous insulin","adjustments":["Continue the person's long-acting basal insulin at the usual dose and time.","When glucose falls below 14 mmol/L, start 10% glucose and consider reducing the fixed-rate infusion to 0.05 units/kg/hour.","Escalate if ketones are not falling by at least 0.5 mmol/L/hour or bicarbonate is not rising by at least 3 mmol/L/hour."],"monitoring":["Capillary glucose and ketones hourly.","Venous pH, bicarbonate and potassium at 60 minutes, 2 hours and every 2 hours thereafter.","Laboratory electrolytes at least every 4 hours and continuous clinical assessment of fluid balance."],"sourceTitle":"The Management of Diabetic Ketoacidosis in Adults","sourceUrl":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf","sourceEdition":"Joint British Diabetes Societies for Inpatient Care, revised March 2023; PDF pages 9 to 11 and 18 to 25; diagnostic criteria, fluid replacement, fixed-rate intravenous insulin infusion, potassium replacement, monitoring and resolution"}],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with diabetic ketoacidosis; this limited extraction covers diagnostic criteria, initial 0.9% sodium chloride, fixed-rate intravenous soluble human insulin, potassium thresholds, dextrose addition, monitoring and biochemical resolution. This March 2023 UK professional guideline predates the 2024 international hyperglycaemic-crises consensus and requires reconciliation with that consensus and the current Saudi emergency, endocrine and critical-care protocol before approval. The source advises cautious fluid replacement in ages 18 to 25, older people, pregnancy, heart failure and renal failure. Exact contraindications are not provided as a complete set; local prescribing and infusion safeguards are mandatory. Paediatric DKA is outside scope. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"42adcc19-664f-4472-b311-5e6d17e87dab","title":"The Management of Diabetic Ketoacidosis in Adults","issuer":"Other","edition":"Joint British Diabetes Societies for Inpatient Care, revised March 2023","url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf","locator":"PDF pages 9 to 11 and 18 to 25; diagnostic criteria, fluid replacement, fixed-rate intravenous insulin infusion, potassium replacement, monitoring and resolution","primary_source":true}],"selection_rationale":"Unverified scope: Adults with diabetic ketoacidosis; this limited extraction covers diagnostic criteria, initial 0.9% sodium chloride, fixed-rate intravenous soluble human insulin, potassium thresholds, dextrose addition, monitoring and biochemical resolution."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Capillary glucose, blood ketones and venous blood gas","clinical_question":"Are the biochemical criteria for adult DKA present?","expected_finding":"The JBDS criteria are glucose above 11 mmol/L or known diabetes, capillary ketones above 3.0 mmol/L or urine ketones above 2+, and venous pH below 7.3 and/or bicarbonate below 15 mmol/L.","decision_rationale":"All three domains establish hyperglycaemia or diabetes, ketosis and metabolic acidosis.","timeframe":"Immediately at presentation"},{"test":"Hourly capillary glucose and ketones","clinical_question":"Are glucose and ketones falling at the expected rate?","expected_finding":"Hourly bedside trends guide insulin and dextrose adjustment.","decision_rationale":"Ketone clearance, rather than glucose alone, is the principal marker of insulin response.","timeframe":"Hourly during active treatment"},{"test":"Venous pH, bicarbonate, potassium and serum electrolytes","clinical_question":"Is acidosis resolving and is potassium replacement safe?","expected_finding":"Repeat venous pH, bicarbonate and potassium at 60 minutes, 2 hours and then every 2 hours; check laboratory electrolytes at least every 4 hours.","decision_rationale":"Insulin and fluid therapy can rapidly change potassium and acid-base status.","timeframe":"At 60 minutes, 2 hours, then every 2 hours; laboratory electrolytes every 4 hours"}],"evidence":{"sources":[{"id":"42adcc19-664f-4472-b311-5e6d17e87dab","title":"The Management of Diabetic Ketoacidosis in Adults","issuer":"Other","edition":"Joint British Diabetes Societies for Inpatient Care, revised March 2023","url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf","locator":"PDF pages 9 to 11 and 18 to 25; diagnostic criteria, fluid replacement, fixed-rate intravenous insulin infusion, potassium replacement, monitoring and resolution","primary_source":true}],"selection_rationale":"Unverified scope: Adults with diabetic ketoacidosis; this limited extraction covers diagnostic criteria, initial 0.9% sodium chloride, fixed-rate intravenous soluble human insulin, potassium thresholds, dextrose addition, monitoring and biochemical resolution."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"If systolic blood pressure is below 90 mmHg, give 500 mL 0.9% sodium chloride over 10 to 15 minutes and reassess with senior and critical-care input; once pressure is above 90 mmHg, give 1 litre over 60 minutes. If systolic pressure is at least 90 mmHg initially, give 1 litre over the first 60 minutes.","timeframe":"Immediately"},{"instruction":"Add potassium chloride to fluids according to serum potassium: none above 5.5 mmol/L, 40 mmol/L when 3.5 to 5.5 mmol/L, and obtain urgent senior review below 3.5 mmol/L.","timeframe":"With each fluid bag after potassium review"},{"instruction":"Start 10% glucose at 125 mL/hour when blood glucose falls below 14 mmol/L while continuing insulin for ketone clearance; consider reducing the insulin rate to 0.05 units/kg/hour.","timeframe":"When blood glucose is below 14 mmol/L"},{"instruction":"Avoid a priming insulin bolus and do not routinely use bicarbonate or phosphate.","timeframe":"Throughout active treatment"},{"instruction":"Review gaps: This March 2023 UK professional guideline predates the 2024 international hyperglycaemic-crises consensus and requires reconciliation with that consensus and the current Saudi emergency, endocrine and critical-care protocol before approval. The source advises cautious fluid replacement in ages 18 to 25, older people, pregnancy, heart failure and renal failure. Exact contraindications are not provided as a complete set; local prescribing and infusion safeguards are mandatory. Paediatric DKA is outside scope. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"42adcc19-664f-4472-b311-5e6d17e87dab","title":"The Management of Diabetic Ketoacidosis in Adults","issuer":"Other","edition":"Joint British Diabetes Societies for Inpatient Care, revised March 2023","url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf","locator":"PDF pages 9 to 11 and 18 to 25; diagnostic criteria, fluid replacement, fixed-rate intravenous insulin infusion, potassium replacement, monitoring and resolution","primary_source":true}],"selection_rationale":"Unverified scope: Adults with diabetic ketoacidosis; this limited extraction covers diagnostic criteria, initial 0.9% sodium chloride, fixed-rate intravenous soluble human insulin, potassium thresholds, dextrose addition, monitoring and biochemical resolution."}}]},"nonClinicalManagement":{"patientEducation":["Explain diabetic ketoacidosis in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Endocrinology / Emergency Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}}]$population$)
